/**
 * The Watch D3's blood-pressure and ECG cards and pages, rendered from REAL recordings:
 * 白い熊's two ECGs of 2026-10-17 (the inconclusive one's first ten seconds, with the electrode
 * settling that once flattened the scale, and the whole sinus-rhythm one), embedded as the watch's
 * own float32 bytes. The blood-pressure readings are the first real one (129/88, pulse 81) and
 * invented neighbours to give the chart a shape.
 *
 * **`@PreviewTest` is not optional** — the engine discovers that annotation, not `@Preview`.
 */

private val ECG_SINUS_B64 = listOf(
    "",
    "",
    "",
    "",
)

private val ECG_SETTLING_B64 = listOf(
    "",
    "",
)

private fun bytes(parts: List<String>): ByteArray =
    parts.map { java.util.Base64.getDecoder().decode(it) }.reduce { a, b -> a + b }

private val SINUS = HuaweiEcgRecording(
    startMs = 1_792_261_503_000L, endMs = 1_792_261_533_000L, verdict = HuaweiEcg.VERDICT_SINUS,
    meanHr = 80, analysisVersion = "V1.0.0.27", sampleRate = 500, samples = HuaweiEcg.decode(bytes(ECG_SINUS_B64)),
)
private val SETTLING = HuaweiEcgRecording(
    startMs = 1_792_261_430_000L, endMs = 1_792_261_440_000L, verdict = HuaweiEcg.VERDICT_INCONCLUSIVE,
    meanHr = 82, analysisVersion = "V1.0.0.27", sampleRate = 500, samples = HuaweiEcg.decode(bytes(ECG_SETTLING_B64)),
)

private const val END = 1_792_310_400_000L          // 2026-10-18 morning
/** INVENTED readings, newest first, chosen to reach every grade and to put two on one day. */
private val READINGS = listOf(
    HuaweiBpReading(END - 1 * 3_600_000L, 145.0, 97.0, 73.0),
    HuaweiBpReading(END - 25 * 3_600_000L, 135.0, 98.0, 75.0),
    HuaweiBpReading(END - 25 * 3_600_000L - 60_000L, 162.0, 101.0, 70.0),
    HuaweiBpReading(END - 49 * 3_600_000L, 137.0, 86.0, 70.0),
    HuaweiBpReading(END - 73 * 3_600_000L, 124.0, 82.0, 78.0),
    HuaweiBpReading(END - 97 * 3_600_000L, 116.0, 76.0, 81.0),
    HuaweiBpReading(END - 121 * 3_600_000L, 129.0, 88.0, 81.0),
)

/** INVENTED: six weeks of one reading a morning, across a month's end — the strip has to scroll. */
private val SIX_WEEKS = (0 until 42).map { d ->
    val sys = 118.0 + (d * 37 % 31)
    HuaweiBpReading(END - d * 86_400_000L, sys, sys * 0.66 + (d % 5), 72.0)
}

private val BP = BloodPressureChart(
    dumbbells = HourlyEnvelope.dumbbells(
        READINGS.reversed().map { ChartPoint(it.tMs, it.systolic) },
        READINGS.reversed().map { ChartPoint(it.tMs, it.diastolic) },
    ),
    headline = "124/83", systolicRange = "121–132", diastolicRange = "80–88",
)


/** 白い熊's real arrhythmia checks, 2026-10-17 22:36 → 2026-10-18 13:30 (all normal), as synced. */
private val PWA_REAL = listOf(
    1792269403L, 1792270237L, 1792273236L, 1792275636L, 1792276238L, 1792277436L, 1792278635L, 1792279236L, 1792279835L, 1792280434L, 1792281035L, 1792283435L, 1792284036L, 1792284634L, 1792285235L, 1792285834L, 1792286435L, 1792287035L, 1792287634L, 1792288235L, 1792288834L, 1792290634L, 1792291846L, 1792292437L, 1792293035L, 1792293635L, 1792294238L, 1792295435L, 1792296035L, 1792296635L, 1792297236L, 1792297835L, 1792299035L, 1792302638L, 1792309236L, 1792315837L
).map { HuaweiPwaCheck(it * 1000L, 0) }.reversed()

/** The same, with one INVENTED not-normal check, so the outline and its wording can be seen. */
private val PWA_WITH_ONE = (PWA_REAL + HuaweiPwaCheck(1_792_281_635_000L, 1)).sortedByDescending { it.tMs }

private const val PWA_NOW = 1_792_334_400_000L     // 2026-10-18 17:20

@Composable
private fun Frame(lang: BandLanguage, content: @Composable () -> Unit) {
    OpenTaskerTheme {
        Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
            CompositionLocalProvider(LocalBandLanguage provides lang) { content() }
        }
    }
}

@PreviewTest
@Preview(name = "D3 cards — English", widthDp = 413, heightDp = 560, showBackground = true)
@Composable
fun D3CardsEnglish() = Frame(BandLanguage.EN) {
    androidx.compose.foundation.layout.Column {
        HuaweiBloodPressureCard(BP, READINGS) {}
        HuaweiEcgCard(listOf(SINUS, SETTLING)) {}
    }
}

